// coin cascade: a shower of bright metallic clinks, thinning out
CUES.coins = () => {
  reseed(31);
  const out = new Stereo(2.6);
  let t = 0;
  for (let k = 0; k < 46; k++) {
    const f = rr(2400, 4600);
    const c = bell(f, { dur: rr(0.25, 0.6), gain: 0.25, parts: [[1, 1, 1], [1.53, 0.5, 0.6], [2.31, 0.35, 0.4], [3.7, 0.2, 0.25]] });
    out.add(c, t, rr(0.5, 1) * (1 - k / 60), rr(-0.8, 0.8));
    out.add(mul(biquad(noise(S(0.01)), 'hp', 5000, 0.7), expDecay(S(0.01), 0.002)), t, 0.15, rr(-0.8, 0.8));
    t += 0.018 + 0.05 * (k / 46) ** 1.6 * rr(0.4, 1.6);
  }
  freeverb(out, { room: 0.6, wet: 0.15 });
  master(out, { peakDb: -2, rmsDb: -20 });
  return out;
};

// sad trombone: "wah wah wah waaah" with a plunger mute and a wobbly last note
CUES.sadtrombone = () => {
  reseed(41);
  const out = new Stereo(3.6);
  const notes = [[58, 0, 0.42], [57, 0.5, 0.42], [56, 1.0, 0.42], [55, 1.5, 1.5]];
  for (const [m, t, d] of notes) {
    const last = t >= 1.5;
    const n = S(d + 0.25);
    const f0 = mtof(m - 12);
    const fq = (i) => { const tt = i / SR; const sc = tt < 0.07 ? 1 - 0.05 * (1 - tt / 0.07) : 1; const w = last && tt > 0.25 ? 2 ** (Math.sin(TAU * 5.5 * (tt - 0.25)) * 0.35 / 12) * 2 ** (-Math.min(1, (tt - 0.25) / 1.3) * 0.7 / 12) : 1; return f0 * sc * w; };
    let y = addInto(saw(n, fq), saw(n, (i) => fq(i) * 1.003), 0.6);
    const e = adsr(n, { a: 0.05, d: 0.1, s: 0.85, r: 0.18, hold: d });
    // plunger "wah": a formant that opens then closes on every note (and wobbles on the last)
    y = biquad(y, 'bp', (i) => { const k = Math.min(1, i / S(d)); return last ? 450 + 650 * (0.5 + 0.5 * Math.sin(TAU * 2.6 * i / SR)) * (1 - k * 0.5) : 380 + 900 * Math.sin(Math.min(1, k * 1.4) * Math.PI); }, 2.2);
    out.add(mul(scale(y, 0.9), e), t, 0.9, 0);
  }
  freeverb(out, { room: 0.6, wet: 0.2 });
  master(out, { peakDb: -1.5, rmsDb: -17 });
  return out;
};

// photo-finish heartbeat: five lub-dubs over a low tension drone, speeding up slightly
CUES.heartbeat = () => {
  reseed(51);
  const out = new Stereo(4.6);
  let t = 0.05;
  for (let k = 0; k < 5; k++) {
    const beat = (f, g) => { // a thump with harmonics (laptop speakers can't play 60 Hz alone) and a soft flesh "thud"
      const n = S(0.35); let p = 0; const y = new Float32Array(n);
      for (let i = 0; i < n; i++) { const tt = i / SR; p += f * (1 + 0.8 * Math.exp(-tt * 40)) / SR; y[i] = Math.tanh(2.2 * Math.sin(TAU * p)) * Math.exp(-tt * 14); }
      addInto(y, mul(biquad(noise(n), 'bp', 220, 1.2), expDecay(n, 0.03, 0.002)), 0.6);
      return scale(biquad(y, 'lp', 420, 0.7), g);
    };
    out.add(beat(58, 1), t, 1, 0); out.add(beat(50, 0.75), t + 0.21, 1, 0);
    t += 60 / (78 + k * 5);
  }
  const n = out.n; // tension: a low drone and a high filtered string swell
  const drone = mul(biquad(addInto(saw(n, mtof(33)), saw(n, mtof(33) * 1.005), 1), 'lp', 140, 0.8), adsr(n, { a: 1.5, d: 0.1, s: 1, r: 0.8, hold: 3.6 }));
  out.add(drone, 0, 0.18, 0);
  out.add(strings(81, 3.4, { a: 2.5, r: 0.8, bright: 2000, trem: 7 }), 0.2, 0.08, 0.3);
  out.add(strings(80, 3.4, { a: 2.5, r: 0.8, bright: 2000, trem: 6.5 }), 0.2, 0.08, -0.3);
  master(out, { peakDb: -1, rmsDb: -16 });
  return out;
};

