CUES.crowd_roar = () => { reseed(62); const o = crowd(6.5, { voices: 40, cheer: 1.4, swellAt: 0.3, applause: 0.9 }); master(o, { peakDb: -1.5, rmsDb: -17 }); return o; };

// cutscene stings
