  const bn = S(0.6); let p = 0; const boing = new Float32Array(bn);
  for (let i = 0; i < bn; i++) { const t = i / SR; p += (110 + 70 * Math.sin(TAU * 9 * t) * Math.exp(-t * 4)) / SR; boing[i] = Math.sin(TAU * p) * Math.exp(-t * 5); }
