// ------------------------------------------------------------------------------------------------------
// MUSIC LOOPS (stems that loop in sync; each file = loop + its natural tail, overlapped at playback)
// ------------------------------------------------------------------------------------------------------
const MUSIC = {};
function loopStems(name, { bpm, bars, beatsPerBar = 4, tail = 2.5, stems }) {
  const B = seq(bpm), loopS = B(bars * beatsPerBar);
  const out = {};
  for (const [stem, fn] of Object.entries(stems)) { const buf = new Stereo(loopS + tail); fn(buf, B, loopS); out[stem] = buf; }
  return { loopS, tailS: tail, bpm, stems: out };
}

// lobby: a relaxed, warm bed (e-piano, plucked bass, brushes, a few glockenspiel notes)
MUSIC.lobby = () => {
  reseed(101);
  const prog = ['Cmaj7', 'Am7', 'Fmaj7', 'G7', 'Cmaj7', 'Am7', 'Dm7', 'G7'];
  return loopStems('lobby', {
    bpm: 96, bars: 8, tail: 2.5,
    stems: {
      lobby: (o, B) => {
        prog.forEach((c, bar) => {
          const ch = CHORD[c]; const b0 = bar * 4;
          [0, 1.5, 2.5].forEach((off, k) => ch.forEach((m, j) => o.add(epiano(m + (j === 0 && k ? 12 : 0), B(k === 0 ? 1.4 : 0.9), { vel: k === 0 ? 0.75 : 0.5 }), B(b0 + off) + j * 0.006, 0.55, j % 2 ? 0.35 : -0.35)));
          const root = ch[0] - 24 + (ch[0] < 55 ? 12 : 0);
          [[0, 1.4], [1.5, 0.45], [2, 0.9], [3, 0.4], [3.5, 0.45]].forEach(([off, d], k) => o.add(bassPluck(k === 3 ? root + 7 : root, B(d)), B(b0 + off), 0.42, 0));
          for (let e = 0; e < 8; e++) o.add(shaker(e % 2 ? 1 : 0.6), B(b0 + e / 2 + (e % 2 ? 0.06 : 0)), 0.55, 0.4);
          o.add(kick(0.55), B(b0), 0.28); o.add(kick(0.4), B(b0 + 2.5), 0.28);
          o.add(snare(0.35, { tone: 220, len: 0.16 }), B(b0 + 1), 0.35, -0.2); o.add(snare(0.35, { tone: 220, len: 0.16 }), B(b0 + 3), 0.35, -0.2);
        });
        const mel = [[76, 0.5], [79, 1.5], [81, 4.5], [79, 6], [76, 8.5], [74, 10], [72, 12.5], [76, 13.5], [77, 16.5], [76, 18], [74, 20.5], [72, 24.5], [74, 26], [79, 28.5], [77, 30]];
        for (const [m, b] of mel) o.add(glock(m + 12, 1.3), B(b), 0.35, 0.5);
        freeverb(o, { room: 0.75, wet: 0.22 });
      },
    },
  });
};

// betting: a tense game-show countdown bed. Stem A: pizzicato ostinato, pulse bass, ticks; Stem B (last 20 s): tremolo
// strings, double-time ticks and a rising timpani pulse.
MUSIC.betting = () => {
  reseed(111);
  const prog = ['Am', 'Am', 'F', 'F', 'Dm', 'Dm', 'E', 'E7'];
  return loopStems('betting', {
    bpm: 120, bars: 8, tail: 2,
    stems: {
      bet_a: (o, B) => {
        prog.forEach((c, bar) => {
          const ch = CHORD[c]; const b0 = bar * 4;
          const pat = [ch[0], ch[2], ch[0] + 12, ch[2], ch[1] + 12, ch[2], ch[0] + 12, ch[2]];
          pat.forEach((m, k) => o.add(pizz(m, 0.4), B(b0 + k / 2), k % 4 === 0 ? 0.75 : 0.5, k % 2 ? 0.35 : -0.35));
          for (let q = 0; q < 4; q++) o.add(synthBass(ch[0] - 12, B(0.4), { cut: 500 }), B(b0 + q), 0.3, 0);
          for (let e = 0; e < 8; e++) o.add(tick(e % 2 ? 0.5 : 1), B(b0 + e / 2), 0.32, 0.55);
          o.add(kick(0.7, { tight: 1.4 }), B(b0), 0.35); o.add(kick(0.5, { tight: 1.4 }), B(b0 + 2), 0.3);
          o.add(strings(ch[2] + 12, B(4) * 0.97, { a: 0.4, bright: 2200 }), B(b0), 0.12, 0.2);
        });
        freeverb(o, { room: 0.6, wet: 0.16 });
      },
      bet_b: (o, B) => {
        prog.forEach((c, bar) => {
          const ch = CHORD[c]; const b0 = bar * 4;
          ch.forEach((m, k) => o.add(strings(m + 12, B(4) * 0.97, { a: 0.05, bright: 3200, trem: 8 }), B(b0), 0.14, k % 2 ? 0.5 : -0.5));
          for (let s = 0; s < 16; s++) o.add(woodblock(s % 4 === 0 ? 86 : 91, s % 4 === 0 ? 1 : 0.55), B(b0 + s / 4), 0.22, -0.5);
          for (let q = 0; q < 4; q++) o.add(timpani(ch[0] - 12, 0.5 + 0.12 * q, 0.5), B(b0 + q), 0.25);
          if (bar % 2 === 1) o.add(riser(B(4), { f1: 300, f2: 6000, gain: 0.1 }), B(b0), 1, 0);
        });
        freeverb(o, { room: 0.6, wet: 0.16 });
      },
    },
  });
};

// race: a driving sports-broadcast groove in D minor. Stem A plays throughout; stem B (the final km) adds a brass
// melody, 16th hats, crashes and a string ostinato, so the music builds without changing key or tempo.
MUSIC.race = () => {
  reseed(121);
  const prog = ['Dm', 'Bb', 'C', 'A', 'Dm', 'Bb', 'C', 'A'];
  const low = (c) => { const r = CHORD[c][0]; return r >= 50 ? r - 24 : r - 12; };
  return loopStems('race', {
    bpm: 128, bars: 8, tail: 2,
    stems: {
      race_a: (o, B) => {
        prog.forEach((c, bar) => {
          const ch = CHORD[c]; const b0 = bar * 4; const r = low(c);
          for (let e = 0; e < 8; e++) o.add(synthBass(e % 2 ? r + 12 : r, B(0.42), { cut: 650 }), B(b0 + e / 2), 0.36, 0);
          o.add(kick(1), B(b0), 0.5); o.add(kick(0.8), B(b0 + 2), 0.45); o.add(kick(0.6), B(b0 + 2.75), 0.35);
          o.add(snare(1), B(b0 + 1), 0.55, -0.1); o.add(snare(1), B(b0 + 3), 0.55, -0.1);
          for (let e = 0; e < 8; e++) o.add(hat(e % 2 ? 0.8 : 0.5), B(b0 + e / 2), 0.4, 0.4);
          ch.forEach((m, k) => { o.add(brass(m + 12, B(0.3), { vel: 0.8, a: 0.015, r: 0.1, vibrato: false }), B(b0 + 0.5), 0.13, k % 2 ? 0.45 : -0.45); o.add(brass(m + 12, B(0.3), { vel: 0.7, a: 0.015, r: 0.1, vibrato: false }), B(b0 + 2.5), 0.11, k % 2 ? 0.45 : -0.45); });
          ch.forEach((m, k) => o.add(strings(m + 12, B(4) * 0.96, { a: 0.3, bright: 2400 }), B(b0), 0.08, k % 2 ? -0.5 : 0.5));
        });
        freeverb(o, { room: 0.65, wet: 0.14 });
      },
      race_b: (o, B) => {
        const mel = [[74, 0, 1.5], [72, 1.5, 0.5], [74, 2, 1], [77, 3, 1], [74, 4, 1.5], [70, 5.5, 0.5], [74, 6, 2], [72, 8, 1.5], [76, 9.5, 0.5], [79, 10, 2], [76, 12, 1], [73, 13, 1], [76, 14, 2],
          [74, 16, 1.5], [72, 17.5, 0.5], [74, 18, 1], [77, 19, 1], [81, 20, 1.5], [79, 21.5, 0.5], [77, 22, 2], [79, 24, 1], [76, 25, 1], [72, 26, 2], [73, 28, 1], [76, 29, 1], [81, 30, 2]];
        for (const [m, b, d] of mel) { o.add(brass(m, B(d) * 0.95, { vel: 1, bright: 1.1 }), B(b), 0.3, -0.1); o.add(brass(m - 12, B(d) * 0.95, { vel: 0.8 }), B(b), 0.18, 0.15); }
        prog.forEach((c, bar) => {
          const ch = CHORD[c]; const b0 = bar * 4;
          for (let s = 0; s < 16; s++) o.add(hat(s % 4 === 2 ? 1 : 0.55, s % 8 === 6), B(b0 + s / 4), 0.28, -0.4);
          for (let s = 0; s < 16; s++) o.add(pizz(ch[s % 3] + 24, 0.18), B(b0 + s / 4), 0.22, s % 2 ? 0.5 : -0.5);
          if (bar % 2 === 0) o.add(crash(0.9, 2), B(b0), 0.35, 0.3);
          o.add(clap(0.8), B(b0 + 1), 0.25, 0.1); o.add(clap(0.8), B(b0 + 3), 0.25, 0.1);
          if (bar % 4 === 3) [[50, 3], [47, 3.25], [45, 3.5], [43, 3.75]].forEach(([m, b]) => o.add(tom(m, 0.9), B(b0 + b), 0.5, 0));
        });
        freeverb(o, { room: 0.7, wet: 0.18 });
      },
    },
  });
};

// ======================================================================================================
// render + encode
// ======================================================================================================
function writeWav(file, buf) {
  const n = buf.n, data = Buffer.alloc(n * 4);
  for (let i = 0; i < n; i++) {
    data.writeInt16LE(Math.max(-32767, Math.min(32767, Math.round(buf.L[i] * 32767))), i * 4);
    data.writeInt16LE(Math.max(-32767, Math.min(32767, Math.round(buf.R[i] * 32767))), i * 4 + 2);
  }
  const h = Buffer.alloc(44);
  h.write('RIFF', 0); h.writeUInt32LE(36 + data.length, 4); h.write('WAVE', 8); h.write('fmt ', 12); h.writeUInt32LE(16, 16);
  h.writeUInt16LE(1, 20); h.writeUInt16LE(2, 22); h.writeUInt32LE(SR, 24); h.writeUInt32LE(SR * 4, 28); h.writeUInt16LE(4, 32); h.writeUInt16LE(16, 34);
  h.write('data', 36); h.writeUInt32LE(data.length, 40);
  fs.writeFileSync(file, Buffer.concat([h, data]));
}
function encode(name, buf, { kbps = 96, mono = false } = {}) {
  const tmp = path.join(os.tmpdir(), `markrun-${name}-${process.pid}.wav`);
  writeWav(tmp, buf);
  if (wavDir) { fs.mkdirSync(wavDir, { recursive: true }); fs.copyFileSync(tmp, path.join(wavDir, `${name}.wav`)); }
  const out = path.join(OUT, `${name}.mp3`);
  execFileSync('ffmpeg', ['-hide_banner', '-loglevel', 'error', '-y', '-i', tmp, ...(mono ? ['-ac', '1'] : []), '-c:a', 'libmp3lame', '-b:a', `${kbps}k`, '-map_metadata', '-1', out]);
  fs.rmSync(tmp);
  return { file: `${name}.mp3`, bytes: fs.statSync(out).size, seconds: +(buf.n / SR).toFixed(3) };
}
function onsetS(buf) { // first sample above -30 dBFS (lets the player check the decoder's alignment)
  for (let i = 0; i < buf.n; i++) if (Math.abs(buf.L[i]) > 0.0316 || Math.abs(buf.R[i]) > 0.0316) return +(i / SR).toFixed(4);
  return 0;
}

fs.mkdirSync(OUT, { recursive: true });
const manifestFile = path.join(OUT, 'manifest.json');
const manifest = fs.existsSync(manifestFile) && only ? JSON.parse(fs.readFileSync(manifestFile, 'utf8')) : { version: 1, cues: {}, music: {} };
const MONO = new Set(['coins', 'sadtrombone', 'heartbeat']);
for (const [name, fn] of Object.entries(CUES)) {
  if (only && !only.includes(name)) continue;
  const t0 = Date.now();
  const buf = fn();
  const r = encode(name, buf, { kbps: MONO.has(name) ? 64 : 96, mono: MONO.has(name) });
  manifest.cues[name] = { file: r.file, seconds: r.seconds };
  console.log(`  ${name.padEnd(14)} ${r.seconds.toFixed(2)}s  ${(r.bytes / 1024).toFixed(0)} KB  (${Date.now() - t0} ms)`);
}
for (const [name, fn] of Object.entries(MUSIC)) {
  if (only && !only.includes(name)) continue;
  const t0 = Date.now();
  const m = fn();
  // one gain for all stems (so their balance survives): normalise the stems' sum
  const sum = new Stereo(m.loopS + m.tailS);
  for (const b of Object.values(m.stems)) { b.L = biquad(b.L, 'hp', 32, 0.7); b.R = biquad(b.R, 'hp', 32, 0.7); sum.mix(b); }
  // the loop as heard: fold the tail back over the start (what plays when the loop repeats)
  const loopN = S(m.loopS);
  for (let i = loopN; i < sum.n; i++) { sum.L[i - loopN] += sum.L[i]; sum.R[i - loopN] += sum.R[i]; }
  let pk = 0, ss = 0; for (let i = 0; i < loopN; i++) { pk = Math.max(pk, Math.abs(sum.L[i]), Math.abs(sum.R[i])); ss += sum.L[i] ** 2 + sum.R[i] ** 2; }
  const rms = Math.sqrt(ss / (2 * loopN));
  const g = Math.min(10 ** (-1.5 / 20) / pk, 10 ** (-17 / 20) / rms);
  const stems = {};
  for (const [stem, b] of Object.entries(m.stems)) {
    for (let i = 0; i < b.n; i++) { b.L[i] = 0.89 * Math.tanh(b.L[i] * g / 0.89); b.R[i] = 0.89 * Math.tanh(b.R[i] * g / 0.89); }
    const r = encode(stem, b, { kbps: 96 });
    stems[stem] = { file: r.file, onsetS: onsetS(b) };
    console.log(`  ${stem.padEnd(14)} ${r.seconds.toFixed(2)}s  ${(r.bytes / 1024).toFixed(0)} KB`);
  }
  manifest.music[name] = { bpm: m.bpm, loopS: +m.loopS.toFixed(6), tailS: m.tailS, stems };
  console.log(`  [${name}] loop ${m.loopS.toFixed(2)}s (${Date.now() - t0} ms)`);
}
fs.writeFileSync(manifestFile, JSON.stringify(manifest, null, 1));
const total = fs.readdirSync(OUT).filter((f) => f.endsWith('.mp3')).reduce((a, f) => a + fs.statSync(path.join(OUT, f)).size, 0);
console.log(`total ${(total / 1024).toFixed(0)} KB in ${path.relative(ROOT, OUT)}/`);
